/* cppi::85d673de30baef27ccf2c5fc9344a1b6c4b81cbbd3f820136cbe92ca63cde517 */
select run_date ,ruleset_id ,rule_description, rule_name ,rule_type  FROM dataops.dq_results
WHERE table_name = 'ma_holding_lookthrough'

/* cppi::ddbb448a024317d345b3a3f53657c6563ea670b04adeb87f1a23b8c23b54843b */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-24' and end_date = '2025-04-24')
and start_date = '2025-04-24' and end_date = '2025-04-24'

/* cppi::23da796f33aa058594badbc4ddde92ecfe9705934033dcbcf0f1582ca946cb88 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-28' and end_date = '2025-04-28')
and start_date = '2025-04-28' and end_date = '2025-04-28'

/* cppi::95cb22e2338ccf54035915a280187a5db0607a47bdb7e430af79e0cbd4daec1b */
select business_date as date_, security_id, 'SP500_45' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-09' and business_date <= date '2025-06-11' and weight_ndo>0 and id_cppib_index = 'SP500_45_GR_USD_0_0' and security_id is not null

